        /// <param name="gateID"> </param>
        /// <param name="usePayWall"> </param>
        /// <param name="payWallID"> </param>
        /// <param name="creatorFlags"> </param>
        /// <param name="wallet"> </param>
        public async Task Post(PaymentTransaction mbrPayment, AssetTransferTransaction tip, ulong timestamp, byte[] nonce, byte[] cid, ulong gateID, bool usePayWall, ulong payWallID, ulong creatorFlags, ulong wallet, Account _tx_sender, ulong? _tx_fee, string _tx_note = "", ulong _tx_roundValidity = 1000, List<BoxRef>? _tx_boxes = null, List<Transaction>? _tx_transactions = null, List<ulong>? _tx_assets = null, List<ulong>? _tx_apps = null, List<Address>? _tx_accounts = null, AVM.ClientGenerator.Core.OnCompleteType _tx_callType = AVM.ClientGenerator.Core.OnCompleteType.NoOp)
