            var cidAbi = new AVM.ClientGenerator.ABI.ARC4.Types.FixedArray<AVM.ClientGenerator.ABI.ARC4.Types.Byte>(36, "byte"); cidAbi.From(cid);
            var gateIDAbi = new AVM.ClientGenerator.ABI.ARC4.Types.UInt64(); gateIDAbi.From(gateID);
            var usePayWallAbi = new AVM.ClientGenerator.ABI.ARC4.Types.Bool(); usePayWallAbi.From(usePayWall);
            var payWallIDAbi = new AVM.ClientGenerator.ABI.ARC4.Types.UInt64(); payWallIDAbi.From(payWallID);
