        ///<summary>
        ///Create the sender's social meta. `user` must be the sender (S-02; it stays in the ABI for
        ///compatibility). The meta stores the VERIFIED wallet `principalOf(dao, wallet).wallet` (0 for a
        ///plain account), which later routes creator tips (re-checked at read time by `tipWallet`).
        ///</summary>
        /// <param name="mbrPayment"> </param>
        /// <param name="user"> </param>
        /// <param name="automated"> </param>
        /// <param name="subscriptionIndex"> </param>
        /// <param name="NFD"> </param>
        /// <param name="akitaNFT"> </param>
        /// <param name="wallet"> </param>
        public async Task<ulong> InitMeta(PaymentTransaction mbrPayment, Algorand.Address user, bool automated, ulong subscriptionIndex, ulong NFD, ulong akitaNFT, ulong wallet, Account _tx_sender, ulong? _tx_fee, string _tx_note = "", ulong _tx_roundValidity = 1000, List<BoxRef>? _tx_boxes = null, List<Transaction>? _tx_transactions = null, List<ulong>? _tx_assets = null, List<ulong>? _tx_apps = null, List<Address>? _tx_accounts = null, AVM.ClientGenerator.Core.OnCompleteType _tx_callType = AVM.ClientGenerator.Core.OnCompleteType.NoOp)
        {
            _tx_boxes ??= new List<BoxRef>();
            _tx_transactions ??= new List<Transaction>();
            _tx_assets ??= new List<ulong>();
            _tx_apps ??= new List<ulong>();
            _tx_accounts ??= new List<Address>();
            _tx_transactions.AddRange(new List<Transaction> { mbrPayment });
            byte[] abiHandle = { 165, 216, 145, 44 };
            var userAbi = new AVM.ClientGenerator.ABI.ARC4.Types.Address(); userAbi.From(user);
            var automatedAbi = new AVM.ClientGenerator.ABI.ARC4.Types.Bool(); automatedAbi.From(automated);
            var subscriptionIndexAbi = new AVM.ClientGenerator.ABI.ARC4.Types.UInt64(); subscriptionIndexAbi.From(subscriptionIndex);
            var NFDAbi = new AVM.ClientGenerator.ABI.ARC4.Types.UInt64(); NFDAbi.From(NFD);
            var akitaNFTAbi = new AVM.ClientGenerator.ABI.ARC4.Types.UInt64(); akitaNFTAbi.From(akitaNFT);
            var walletAbi = new AVM.ClientGenerator.ABI.ARC4.Types.UInt64(); walletAbi.From(wallet);

            var result = await base.CallApp(new List<object> { abiHandle, mbrPayment, userAbi, automatedAbi, subscriptionIndexAbi, NFDAbi, akitaNFTAbi, walletAbi }, _tx_fee: _tx_fee, _tx_callType: _tx_callType, _tx_roundValidity: _tx_roundValidity, _tx_note: _tx_note, _tx_sender: _tx_sender, _tx_transactions: _tx_transactions, _tx_apps: _tx_apps, _tx_assets: _tx_assets, _tx_accounts: _tx_accounts, _tx_boxes: _tx_boxes);
            var lastLogBytes = result.Last();
            if (lastLogBytes.Length < 4 || lastLogBytes[0] != 21 || lastLogBytes[1] != 31 || lastLogBytes[2] != 124 || lastLogBytes[3] != 117) throw new Exception("Invalid ABI handle");
            var lastLogReturnData = lastLogBytes.Skip(4).ToArray();
            var returnValueObj = new AVM.ClientGenerator.ABI.ARC4.Types.UInt64();
            returnValueObj.Decode(lastLogReturnData);
